  let closed = false;
  return {origin, url: origin + '/#' + token, close: async () => { if (closed) return; closed = true; server.closeIdleConnections(); await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())); workspace.close(); }};
}

